                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y2+dy,x2+dx
                            if 0<=ny<H and 0<=nx<W and I[ny][nx]==2 and (ny,nx) not in seen:
                                seen.add((ny,nx));st.append((ny,nx))
                ys=[p[0] for p in c];xs=[p[1] for p in c]
                ty,mx=min(ys),min(xs)
                # canonical stroke?
                pat=''.join(''.join('#' if I[y][x]==2 else '.' for x in range(mx,max(xs)+1)) for y in range(ty,max(ys)+1))
                if pat in ('.#.###','###.#.'):
