    H=len(I);W=len(I[0]);seen=set();res=[]
    for y in range(H):
        for x in range(W):
            if I[y][x]==2 and (y,x) not in seen:
                st=[(y,x)];seen.add((y,x));c=[(y,x)]
                while st:
                    y2,x2=st.pop()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y2+dy,x2+dx
                        if 0<=ny<H and 0<=nx<W and I[ny][nx]==2 and (ny,nx) not in seen:
                            seen.add((ny,nx));st.append((ny,nx));c.append((ny,nx))
                res.append(c)
    return res
